/**
 * The prostate cancer roadmap and the open questions (ideas) for the September 2026 deep dive. Every dated claim in
 * the steps points at a paper record in the prostate-evidence files or in the wider corpus, or at a
 * ClinicalTrials.gov record; the `watch` dates are quoted from the registry as read on 2026-09-25 and are not
 * predictions. The id is `prostate-roadmap`: the cancer record is `prostate` and lives at /cancers/prostate/, so
 * there is no URL collision, and the hormonal therapy, early detection, radiopharmaceutical and targeted therapy
 * roadmaps are the cross-cancer routes this one joins.
 */
type R = Omit<RoadmapInput, "kind" | "asOf">;
const r = (x: R): RoadmapInput => ({ kind: "roadmap", asOf, ...x });
type I = Omit<IdeaInput, "kind" | "asOf">;
const idea = (x: I): IdeaInput => ({ kind: "idea", asOf, tags: ["prostate-evidence"], ...x });

