export const prostateIdeas: IdeaInput[] = [
  idea({ id: PROSTATE_IDEAS.hrrTiming,
    name: "Test every man for DNA repair faults on the day his prostate cancer is found to have spread, not three treatments later",
    aka: ["HRR testing at metastatic diagnosis", "germline and tumour DNA repair testing timing prostate"],
    tldr: "About one man in eight with prostate cancer that has spread carries an inherited DNA repair fault, and about one in five has one in the tumour. The drugs for those faults have moved to the beginning of treatment, but the test is still usually done near the end, when it is too late to use the result.",
    summary: "The evidence for testing is settled. Pritchard found presumed deleterious germline DNA repair mutations in 11.8 percent of 692 men with metastatic prostate cancer, against 4.6 percent in localised disease and 2.7 percent in a population without a cancer diagnosis, and found no relation to family history or age at diagnosis. Robinson found BRCA2, BRCA1 and ATM aberrations in 19.3 percent of 150 prospectively sequenced metastatic biopsies, and Chung found homologous recombination repair alterations in 23 percent of 3,476 routinely profiled tumours. Both germline and somatic BRCA alterations predict response to a PARP inhibitor, as TRITON2 showed.\n\nWhat has changed is when the answer is needed. PARP inhibitors were licensed after an androgen receptor drug and a taxane; PROpel, TALAPRO-2 and MAGNITUDE moved them to first-line castration-resistant disease, and TALAPRO-3 and AMPLITUDE have moved them into hormone-sensitive disease. A result that arrives after two lines of treatment can no longer be acted on in the setting where the drug is licensed. The proposal is to make combined germline and tumour homologous recombination repair testing an automatic step triggered by the diagnosis of metastasis, in the same way a hormone receptor stain is triggered by a breast biopsy, with the result reported before the first systemic treatment is chosen and with the germline half routed to a family testing pathway.\n\n" + UK_PAGE_NOTE,
    hypothesis: "Reflex germline and tumour homologous recombination repair testing at the moment of metastatic diagnosis, rather than on clinician request at castration resistance, increases the proportion of eligible men who receive a PARP inhibitor in the setting where it is licensed, increases the proportion of first-degree relatives who are offered cascade testing, and does so at a testing cost per actionable result lower than the cost of the current late pathway, which sequences men who never reach the relevant line.",
    rationale: "Three things make the timing argument rather than the testing argument the live one. First, carriers cannot be identified clinically: Pritchard showed mutation frequency does not differ by family history or age, so selective testing misses most of them. Second, the drug has moved: the licensed settings for PARP inhibition now start at first-line castration-resistant and, in TALAPRO-3 and AMPLITUDE, hormone-sensitive disease, which is before most men are currently tested. Third, the test result has a second use that is lost entirely by testing late, which is the 8 percent of men in the Stand Up To Cancer cohort with an actionable pathogenic germline alteration whose relatives carry breast, ovarian and pancreatic risk. Testing at metastatic diagnosis also takes place when tumour tissue is more likely to be available and adequate; TRITON3 screened 4,855 men to randomise 405, which is the cost of finding carriers late and one at a time.",
    test: "A stepped-wedge implementation trial across cancer networks, switching from clinician-requested testing to a reflex order fired by the coding of metastatic prostate cancer. Co-primary outcomes: the proportion of men with a homologous recombination repair result available before first-line systemic treatment is chosen, and the proportion of identified germline carriers whose first-degree relatives are offered testing within 12 months. Secondary outcomes: PARP inhibitor use in the licensed setting, turnaround time, tissue adequacy failure rate, and cost per actionable result against the current pathway. Two to three years, and it can be run inside an existing service rather than as a new trial infrastructure.",
    maturity: "early-clinical", actor: "clinic", cost: "medium", horizonYears: 3,
    cancers: [PROSTATE, MHSPC, MCRPC, NMCRPC],
    keyPapers: ["paper-pritchard-inherited-dna-repair-metastatic-prostate-nejm-2016", "paper-robinson-integrative-clinical-genomics-advanced-prostate-cell-2015", "paper-chung-comprehensive-genomic-profiling-prostate-jco-po-2019", "paper-abida-triton2-rucaparib-brca-jco-2020", "paper-fizazi-triton3-rucaparib-nejm-2023", "paper-nct04821622-n-engl-j-med-2026"],
    bottlenecks: ["b-hereditary-risk", "b-biomarker-validation", "b-care-fragmentation", "b-knowledge-diffusion"],
    sections: ["diagnostics", "targeted-therapy", "prevention"], technologies: ["germline-testing", "ngs", "liquid-biopsy"],
    targets: ["brca", "atm", "cdk12"], drugs: ["olaparib", "rucaparib", "niraparib", "talazoparib"],
    companies: ["astrazeneca", "johnson-johnson", "pfizer", "myriad-genetics", "foundation-medicine"],
    related: ["idea-prev-reflex-germline-testing", "prostate-roadmap", "targeted-therapy-roadmap"] }),
  idea({ id: PROSTATE_IDEAS.sequence,
    name: "Randomise the order of treatment, not only the drugs: a strategy platform for metastatic prostate cancer",
    aka: ["sequencing trial prostate cancer", "PFS2 strategy trial", "treatment order randomised prostate"],
    tldr: "Metastatic prostate cancer now has six classes of treatment that work, and no trial has ever compared the orders they can be given in. Every trial adds a drug to the front; none asks what should follow it, so the sequence a man receives is decided by habit and by what was licensed first.",
    summary: "Each of the classes was licensed against placebo or against an older drug, in a population defined by what it had already received: docetaxel against mitoxantrone, cabazitaxel after docetaxel, abiraterone and enzalutamide before and after chemotherapy, radium-223 in bone-predominant disease, lutetium-177 PSMA-617 after an androgen receptor drug and a taxane, and PARP inhibitors after progression on an androgen receptor drug. Intensification trials then moved several of them to the first day of metastatic diagnosis. What no trial has done is randomise the order.\n\nThat the order matters is not speculation. TRANSFORMER found identical progression-free survival on its primary endpoint and a difference of 8.6 months in progression-free survival through crossover depending on which arm came first, with a hazard ratio of 0.44. The same trial found prostate-specific antigen progression-free survival on enzalutamide was 3.8 months when it followed abiraterone and 10.9 months when it followed bipolar androgen therapy. CARD showed that switching from one androgen receptor drug to the other is worse than moving to cabazitaxel. The proposal is a standing platform in which the randomisation unit is a strategy rather than an agent, with progression-free survival through the second line as a co-primary endpoint alongside overall survival, and with re-randomisation at each progression. ProBio, which randomises by biomarker signature and adapts on outcome, is the nearest existing design; STAMPEDE2 has the infrastructure.\n\n" + UK_PAGE_NOTE,
    hypothesis: "In metastatic prostate cancer, the sequence in which the available treatment classes are given changes overall survival and time to the second progression by a margin comparable to that between the individual drugs, and a platform that randomises sequences with re-randomisation at progression can detect a difference of three months in progression-free survival through the second line within five years.",
    rationale: "Three lines of argument converge. Mechanistically, resistance to one androgen receptor drug is largely cross-resistance to the other, because both act on the ligand-binding domain and both select for AR-V7 and for lineage switching, whereas taxanes and radioligands do not; so an order that alternates mechanism should outlast one that does not. Empirically, TRANSFORMER measured a sequence effect of 8.6 months in PFS2 with quality of life favouring the same arm. Structurally, no regulator asks for sequence data and no company benefits from generating it, which is precisely the kind of question public platforms exist to answer. The alternative to running the trial is what happens now, which is that sequence is decided by licensing chronology.",
    test: "A publicly funded platform trial with sequence as the randomised unit: at metastatic castration-resistant progression, randomise between pre-specified two-step strategies (androgen receptor pathway inhibitor then taxane; taxane then androgen receptor pathway inhibitor; androgen receptor pathway inhibitor then radioligand where PSMA-positive; and in biomarker-positive men, PARP-containing strategies), with re-randomisation at the second progression. Co-primary endpoints: overall survival and progression-free survival through the second line. Stratify on homologous recombination repair status, PSMA uptake and prior hormone-sensitive intensification. Quality of life and time on treatment collected throughout. Five to seven years to first strategy comparison; reuse an existing platform rather than building new infrastructure.",
    maturity: "early-clinical", actor: "research", cost: "large", horizonYears: 7,
    cancers: [PROSTATE, MHSPC, MCRPC],
    keyPapers: ["paper-denmeade-transformer-bipolar-androgen-therapy-jco-2021", "paper-de-bono-tropic-cabazitaxel-lancet-2010", "paper-therap-lancet-2021", "paper-vision-nejm-2021", "paper-antonarakis-ar-v7-resistance-nejm-2014", "paper-stampede-abiraterone-high-risk-attard-lancet-2022"],
    bottlenecks: ["b-trial-design", "b-combination-space", "b-incentive-misalignment", "b-funding-allocation", "b-resistance"],
    sections: ["hormonal", "chemotherapy", "radiopharma", "targeted-therapy"],
    drugs: ["abiraterone", "enzalutamide", "docetaxel", "cabazitaxel", "pluvicto", "radium-223", "olaparib"],
    technologies: ["radioligand-therapy", "psma-pet"],
    related: ["idea-tr1-standing-platform-per-cancer", "idea-tr1-smart-designs-for-adaptive-strategies", "idea-bio1-alternating-schedules", "prostate-roadmap", "trial-modernisation-roadmap"] }),
  idea({ id: PROSTATE_IDEAS.plasticity,
    name: "Watch for the cancer changing cell type before the biopsy says neuroendocrine, and act on it",
    aka: ["lineage plasticity surveillance prostate", "TP53 RB1 loss monitoring prostate", "pre-emptive platinum neuroendocrine prostate"],
    tldr: "In a minority of men, prostate cancer escapes hormone drugs by becoming a different kind of cell that no longer needs the androgen receptor. By the time a biopsy shows it, the treatment options are almost gone. The genetic changes that allow the switch are detectable years earlier, and nobody is looking for them.",
    summary: "Mu and Ku showed in 2017 that combined loss of TP53 and RB1 function enables prostate cancer cells to shift from androgen receptor-dependent luminal cells to androgen receptor-independent basal-like cells, mediated by SOX2, and that restoring the tumour suppressors reverses it in the laboratory. Beltran had already shown that neuroendocrine prostate cancer arises by divergent clonal evolution from the same tumour rather than as a separate disease. Aggarwal found treatment-emergent small-cell neuroendocrine carcinoma in 17 percent of metastatic biopsies in a prospective cohort. Chung found RB1 alteration enriched in metastatic over primary samples.\n\nThe enabling lesions are therefore known, detectable in circulating tumour DNA, and present before the phenotype changes. What is missing is any protocol that uses them. A man with combined TP53 and RB1 loss who is started on a third androgen receptor-directed line is being given a treatment his tumour is predisposed to escape by the one route that leads nowhere. The proposal is a two-part programme: serial circulating tumour DNA genotyping for TP53 and RB1 status, plus a plasma transcriptional readout of neuroendocrine identity, in men starting an androgen receptor pathway inhibitor for castration-resistant disease; and a randomised test of whether men who convert should switch to platinum-based chemotherapy or a neuroendocrine-directed agent at conversion rather than at biopsy-proven transformation.\n\n" + UK_PAGE_NOTE,
    hypothesis: "In men with castration-resistant prostate cancer, combined TP53 and RB1 loss detected in circulating tumour DNA identifies, months before any histological change, the group in whom further androgen receptor-directed therapy will fail quickly, and switching that group to platinum-based or lineage-directed treatment at the point of molecular conversion rather than at biopsy-proven neuroendocrine transformation improves overall survival.",
    rationale: "The mechanism is established in models and the frequency is established in patients: 17 percent of metastatic biopsies in Aggarwal's cohort were treatment-emergent small-cell neuroendocrine carcinoma, a diagnosis with a median survival measured in months and no approved treatment. The enabling genotype is measurable without a biopsy. And the current pathway, which waits for a clinical suspicion strong enough to justify re-biopsying a man with bone-predominant disease, guarantees that the diagnosis is made late: the trigger for suspicion is usually visceral metastasis or a rising tumour burden with a flat prostate-specific antigen, both of which are late events. Every element of the test exists; none of them is sequenced together prospectively.",
    test: "A prospective cohort with an embedded randomisation. Enrol men starting an androgen receptor pathway inhibitor for castration-resistant disease; collect plasma at baseline and at each cycle for targeted circulating tumour DNA sequencing of TP53, RB1 and PTEN and for a neuroendocrine transcriptional signature; biopsy at progression where safe to establish the histological reference. The observational phase measures how far in advance molecular conversion precedes histological transformation and its positive predictive value. Men who convert are then randomised to immediate platinum-based chemotherapy against continued standard sequencing with treatment change at histological transformation, with overall survival as the primary endpoint. Four years to the lead-time answer, seven to the randomised one.",
    maturity: "preclinical-evidence", actor: "research", cost: "large", horizonYears: 7,
    cancers: [PROSTATE, MCRPC, NEPC],
    keyPapers: ["paper-mu-sox2-lineage-plasticity-science-2017", "paper-ku-rb1-trp53-lineage-plasticity-science-2017", "paper-beltran-nepc-divergent-evolution-nat-med-2016", "paper-aggarwal-t-sccpc-jco-2018", "paper-rubin-mol-cell", "paper-chung-comprehensive-genomic-profiling-prostate-jco-po-2019"],
    bottlenecks: ["b-resistance", "b-tumor-heterogeneity", "b-rare-cancers", "b-biomarker-validation", "b-undruggable-targets"],
    sections: ["diagnostics", "targeted-therapy", "chemotherapy"], technologies: ["liquid-biopsy", "ngs"],
    targets: ["tp53", "rb1", "androgen-receptor"], drugs: ["carboplatin", "cisplatin", "enzalutamide", "abiraterone"],
    terms: ["ctdna", "castration-resistance"],
    related: ["idea-bio1-cfrna-plasticity-tracking", "idea-bio1-ctc-derived-explants", "prostate-roadmap", "ctdna-tests"] }),
  idea({ id: PROSTATE_IDEAS.bat,
    name: "Take high-dose testosterone to phase 3, with progression-free survival through the second line as the primary endpoint",
    aka: ["bipolar androgen therapy phase 3", "supraphysiological testosterone prostate phase 3", "BAT resensitisation trial"],
    tldr: "Giving men with castration-resistant prostate cancer large doses of the hormone the treatment has spent years removing makes a third of them respond, and makes half of them respond again to the drug that had stopped working. It has never been taken to a definitive trial, partly because the endpoint that shows the benefit is not the one trials usually use.",
    summary: "RESTORE gave monthly testosterone cipionate 400 mg to 30 men who had progressed on enzalutamide: 9 of 30 (30 percent) had a 50 percent prostate-specific antigen fall, and 15 of 21 (52 percent) responded when re-challenged with enzalutamide afterwards. TRANSFORMER randomised the approach against enzalutamide in 195 men and found progression-free survival of 5.7 months in both arms, but progression-free survival through crossover of 28.2 against 19.6 months in favour of testosterone first (hazard ratio 0.44, P equals 0.02), prostate-specific antigen progression-free survival on enzalutamide of 10.9 months after testosterone against 3.8 months after abiraterone, and quality of life consistently favouring testosterone.\n\nThe drug is an old generic. There is no commercial sponsor with a reason to run the trial, and the primary endpoint that regulators are used to, progression-free survival on the assigned treatment, is precisely the one on which the approach is flat, because the benefit is resensitisation rather than direct cytotoxicity. That combination is why a treatment with a randomised signal and a quality-of-life advantage has sat at phase 2 since 2021. The proposal is a publicly funded phase 3 in asymptomatic men with low-volume castration-resistant disease, powered on progression-free survival through the second line, with overall survival and patient-reported outcomes as key secondaries.\n\n" + UK_PAGE_NOTE,
    hypothesis: "In asymptomatic men with metastatic castration-resistant prostate cancer and no high-risk sites for tumour flare, a strategy of bipolar androgen therapy followed at progression by an androgen receptor pathway inhibitor improves progression-free survival through the second line and patient-reported quality of life against the reverse strategy, without a detriment in overall survival.",
    rationale: "The mechanism follows directly from the biology of resistance in this disease: castration-resistant cells adapt by amplifying and overexpressing the androgen receptor, which Visakorpi and Chen established, and a cell adapted to a low-ligand environment is vulnerable to a high-ligand one. The clinical signal is randomised, not anecdotal, and it is a sequence effect of 8.6 months in PFS2 with a hazard ratio of 0.44. The quality-of-life direction is unusual: almost every intensification in this disease costs the patient something, and this one does not. The barrier is commercial rather than scientific, which makes it exactly the kind of question a public funder should pick up, and the endpoint problem is soluble by naming PFS2 in the protocol rather than discovering it in the secondary analysis.",
    test: "A publicly funded randomised phase 3 in asymptomatic men with metastatic castration-resistant prostate cancer, excluding those with more than five visceral sites or bone lesions at risk of fracture, randomised to bipolar androgen therapy followed by an androgen receptor pathway inhibitor at progression, or to an androgen receptor pathway inhibitor followed by bipolar androgen therapy. Primary endpoint progression-free survival through the second line; key secondary endpoints overall survival, patient-reported quality of life and sexual function, and cardiovascular and thromboembolic events. Stratify on prior androgen receptor pathway inhibitor exposure and on AR-V7 status. Roughly 500 men and five years.",
    maturity: "early-clinical", actor: "research", cost: "medium", horizonYears: 6,
    cancers: [PROSTATE, MCRPC],
    keyPapers: ["paper-teply-restore-bipolar-androgen-therapy-lancet-oncol-2018", "paper-denmeade-transformer-bipolar-androgen-therapy-jco-2021", "paper-chen-androgen-receptor-overexpression-antiandrogen-resistance-nat-med-2004", "paper-visakorpi-androgen-receptor-amplification-nat-genet-1995", "paper-antonarakis-ar-v7-resistance-nejm-2014"],
    bottlenecks: ["b-generic-repurposing", "b-incentive-misalignment", "b-resistance", "b-trial-design", "b-toxicity-qol"],
    sections: ["hormonal"], drugs: ["enzalutamide", "abiraterone"], targets: ["androgen-receptor"],
    institutions: ["johns-hopkins"], terms: ["castration-resistance", "psa", "quality-of-life"],
    related: ["idea-bio1-alternating-schedules", "idea-tr1-adaptive-therapy-randomised-phase-2", "idea-moon-generics-for-cancer-fund", "prostate-roadmap"] }),
  idea({ id: PROSTATE_IDEAS.metastaticEndpoint,
    name: "Judge a prostate screening programme on metastatic presentation, not on incidence or mortality",
    aka: ["metastasis-free survival screening endpoint prostate", "metastatic presentation as screening outcome"],
    tldr: "Screening trials are judged on deaths, which take fifteen years to count, and on cancers found, which is the wrong direction. Preventing a man from turning up with cancer already in his bones happens three times as often as preventing a death, arrives years earlier, and is the outcome he cares about.",
    summary: "The 2018 United States task force statement quantifies both: screening men aged 55 to 69 may prevent approximately 1.3 deaths from prostate cancer and approximately 3 cases of metastatic prostate cancer per 1,000 men screened over about 13 years. The metastatic endpoint is more than twice as frequent, and it precedes death by years, so a trial powered on it reads out sooner and smaller. It is also the endpoint that separates the benefit of screening from its harm: overdiagnosis inflates incidence, so incidence is actively misleading, and mortality is confounded by improvements in treatment over the decades a screening trial runs.\n\nDraisma showed that mean lead time is 5.4 to 6.9 years, which is the interval within which a metastatic presentation can be prevented and after which it cannot. The proposal is to adopt the rate of de novo metastatic presentation in the invited population as the primary outcome of any new prostate screening programme or trial, reported per 1,000 invited rather than per 1,000 screened, with prostate cancer mortality as a long-term secondary and incidence reported only as a harm. It is a change in what is measured rather than in what is done, which makes it cheap, and it would let the magnetic resonance imaging-first pathways such as Goteborg-2 be evaluated on a timescale on which policy can actually act.\n\n" + UK_PAGE_NOTE,
    hypothesis: "De novo metastatic presentation in the invited population is a valid and substantially more efficient primary endpoint for prostate cancer screening than prostate cancer mortality: it occurs roughly three times as often, precedes mortality by years, is not inflated by overdiagnosis, and would allow a screening pathway to be evaluated in about half the follow-up time with a comparable or smaller sample.",
    rationale: "Incidence is the wrong direction of merit in a disease where a quarter to two thirds of screen-detected cancers may be overdiagnosed, depending on definition and population; a programme that finds more cancers may be doing harm. Mortality is right but slow and confounded: over the 13 to 20 years a screening trial runs, treatment for metastatic disease has repeatedly improved, which dilutes the measured screening effect in a way that has nothing to do with the screening. Metastatic presentation is neither inflated by overdiagnosis nor rescued by better systemic therapy, it is the event that ends curative intent, and the task force's own numbers say it is about three times as common as a prevented death. Reporting per 1,000 invited rather than per 1,000 screened additionally makes uptake part of the measured outcome rather than an excuse for it.",
    test: "Two steps. First, a validation analysis in the existing randomised datasets: re-analyse ERSPC and the Cluster Randomised Trial of PSA Testing with de novo metastatic presentation as the endpoint and measure how many years earlier the observed effect reaches significance, and how closely the metastatic and mortality effects agree. Second, if the surrogacy holds, register metastatic presentation per 1,000 invited as the pre-specified primary outcome of the next generation of screening evaluations, including the magnetic resonance imaging-first pathways, with mortality retained as a long-term secondary. Step one is a secondary analysis of existing data and could be done in a year.",
    maturity: "speculative", actor: "policy", cost: "small", horizonYears: 4,
    cancers: [PROSTATE, LOW_RISK, INTERMEDIATE_RISK, HIGH_RISK],
    keyPapers: ["paper-uspstf-prostate-screening-jama-2018", "paper-schroder-erspc-screening-mortality-nejm-2009", "paper-draisma-lead-time-overdiagnosis-psa-jnci-2009", "paper-martin-jama", "paper-goteborg-2-n-engl-j-med-2022", "paper-loeb-overdiagnosis-overtreatment-prostate-eur-urol-2014"],
    bottlenecks: ["b-early-detection", "b-overdiagnosis", "b-trial-design", "b-prevention-adoption"],
    sections: ["early-detection", "prevention"], technologies: ["prostate-screening-psa-mri", "mri"],
    terms: ["screening", "psa", "overdiagnosis"],
    related: ["idea-prev-mri-first-prostate-screening-prs", "idea-prev-prs-screening-start-age", "early-detection-roadmap", "prostate-roadmap"] }),
  idea({ id: PROSTATE_IDEAS.otherCause,
    name: "Report death from other causes as an outcome of the prostate cancer service, split by deprivation and ethnicity",
    aka: ["other-cause mortality prostate service outcome", "competing mortality prostate cancer equity"],
    tldr: "When Black and white men in the United States are given the same treatment, the gap in dying of prostate cancer largely closes. The gap in dying of everything else does not. Cancer services measure the first and not the second, which means the surviving disparity is invisible to the people best placed to act on it.",
    summary: "Dess and colleagues pooled three cohorts with progressively tighter control of access: a registry, an equal-access surgical system and four randomised radiotherapy trials. After inverse probability weighting, the prostate cancer-specific hazard for Black men fell from 1.30 to 1.09 in the registry, was not significantly different in the equal-access cohort, and was significantly lower in the trial cohort. Other-cause mortality remained significantly higher in two of the three cohorts, at subdistribution hazard ratios of 1.30 and 1.17.\n\nThat pattern has a direct operational meaning. A prostate cancer service that achieves equal treatment has done most of what it can about prostate cancer death and none of what it could about the larger remaining gap. The men in question are on androgen deprivation, which causes weight gain, insulin resistance, dyslipidaemia, loss of bone and muscle and, in some analyses, cardiovascular events; they are seen regularly by the cancer service for years; and their cardiovascular and metabolic risk is managed, if at all, elsewhere. The proposal is narrow and measurable: report other-cause mortality alongside cancer-specific mortality in every prostate cancer service audit, split by deprivation quintile and ethnicity, and make it the outcome against which a hormone therapy cardiometabolic clinic is judged.\n\n" + UK_PAGE_NOTE,
    hypothesis: "Making other-cause mortality a reported and audited outcome of prostate cancer services, split by deprivation and ethnicity, will reveal a larger equity gap than cancer-specific mortality does and will support cardiometabolic intervention embedded in the cancer clinic that narrows it, at a cost per life-year lower than most systemic anticancer therapy in the same disease.",
    rationale: "Prostate cancer has an unusual competing-risk structure: most men diagnosed with it die of something else, and androgen deprivation, the backbone of treatment, is itself a cardiometabolic intervention in the wrong direction. Dess supplies the measurement that separates the two gaps, and shows that the one cancer services already work on largely closes under equal access while the other does not. Nothing in a standard cancer audit captures this, because cancer audits are built around cancer-specific outcomes on the reasonable ground that other deaths are not the service's doing. In a disease treated for a decade with a drug that worsens metabolic health, that reasoning no longer holds.",
    test: "Add other-cause mortality, split by deprivation quintile and by ethnicity, to national prostate cancer audit reporting, using registry linkage to death certification, and publish it alongside cancer-specific mortality by provider. Then run a cluster-randomised trial in which intervention sites embed cardiometabolic assessment and treatment into the androgen deprivation follow-up appointment (blood pressure, lipids, HbA1c, bone density, structured exercise referral) and control sites continue usual referral to primary care, with other-cause mortality at five years as the primary endpoint and cardiovascular events at two years as the interim readout. Reporting can start immediately; the trial takes five years.",
    maturity: "early-clinical", actor: "policy", cost: "medium", horizonYears: 5,
    cancers: [PROSTATE, INTERMEDIATE_RISK, HIGH_RISK, MHSPC, NMCRPC],
    keyPapers: ["paper-dess-black-race-prostate-mortality-jama-oncol-2019", "paper-conti-trans-ancestry-gwas-prostate-nat-genet-2021", "paper-hussain-swog-9346-intermittent-androgen-deprivation-nejm-2013", "paper-langley-lancet", "paper-uspstf-prostate-screening-jama-2018"],
    bottlenecks: ["b-survivorship", "b-global-access", "b-aging-comorbidity", "b-real-world-evidence", "b-care-fragmentation", "b-trial-diversity"],
    sections: ["supportive-care", "hormonal", "nutrition-lifestyle"], terms: ["adt", "quality-of-life"],
    related: ["idea-acc-cardiometabolic-clinic-hormone-therapy", "idea-exercise-as-adjuvant", "idea-acc-risk-stratified-follow-up", "survivorship-roadmap", "prostate-roadmap"] }),
  idea({ id: PROSTATE_IDEAS.perLesion,
    name: "Publish a per-lesion miss rate for every prostate MRI service before it is allowed to guide focal treatment",
    aka: ["per-lesion MRI audit prostate", "whole-mount pathology audit focal therapy", "MRI miss rate reporting"],
    tldr: "Prostate MRI is good at telling you whether a man has a serious cancer and poor at telling you where all of it is. It missed at least one significant tumour in a third of men in the study that checked it against the whole removed prostate. Services that treat part of the gland, or follow men on imaging alone, are relying on the number they do not measure.",
    summary: "PROMIS established per-patient performance: sensitivity of 93 percent for clinically significant cancer against a template mapping biopsy reference, with specificity of 41 percent, which is what justifies using the scan to decide whether to biopsy. Johnson and colleagues measured per-lesion performance by co-registering scans with whole-mount pathology in 588 prostatectomy specimens: 45 percent of all 1,213 foci detected, 65 percent of clinically significant ones, at least one clinically significant focus missed in 34 percent of men overall and 45 percent of men with multifocal disease.\n\nThose two numbers answer different questions and are routinely quoted as if they answered the same one. A triage decision needs the first. Treating one part of the gland and leaving the rest, or following a man for years on imaging without biopsy, needs the second, and no service publishes it. Every centre performing radical prostatectomy after magnetic resonance imaging already generates the data required, because it has the scan and the whole gland. The proposal is that per-lesion sensitivity against whole-mount pathology, stratified by lesion size and grade, becomes a published quality metric, and a precondition for offering focal ablation or imaging-only surveillance.",
    hypothesis: "Per-lesion sensitivity of multiparametric magnetic resonance imaging against whole-mount pathology varies substantially between centres and readers, this variation is measurable from data centres already hold, and publishing it changes which centres offer focal therapy and imaging-only surveillance and reduces the rate of clinically significant cancer found outside the treated or monitored region.",
    rationale: "The per-patient and per-lesion figures differ by around 30 percentage points in the best available study, and the gap is exactly where focal therapy and imaging-only follow-up operate. Reader and protocol variation in prostate magnetic resonance imaging is well documented and is the standing argument for certification, but certification is currently based on reading test cases rather than on a centre's own outcomes. The audit proposed here requires no new imaging, no new pathology and no new consent beyond routine data use: the scan, the whole-mount specimen and the co-registration software all exist, and the comparison is already done retrospectively in research settings. Making it routine turns an unmeasured risk into a published number that patients and commissioners can act on.",
    test: "A multicentre audit in which every centre performing radical prostatectomy after multiparametric magnetic resonance imaging co-registers the pre-operative scan with the whole-mount specimen and reports per-lesion sensitivity for all foci and for clinically significant foci, stratified by lesion diameter, grade group, index versus non-index status and prostate-specific antigen density, with reader-level and scanner-level breakdown. Publish centre-level figures annually. Then test the consequence: a registry comparison of focal therapy outcomes (clinically significant cancer in the untreated gland at three years) between centres above and below the median per-lesion sensitivity. Two years to the first audit round.",
    maturity: "early-clinical", actor: "clinic", cost: "small", horizonYears: 3,
    cancers: [PROSTATE, LOW_RISK, INTERMEDIATE_RISK, HIGH_RISK],
    keyPapers: ["paper-johnson-mpmri-individual-foci-eur-urol-2019", "paper-ahmed-promis-multiparametric-mri-lancet-2017", "paper-precision-mri-targeted-biopsy-nejm-2018", "paper-klotz-active-surveillance-jco-2015"],
    bottlenecks: ["b-biomarker-validation", "b-surgery-radiation-innovation", "b-overdiagnosis", "b-real-world-evidence", "b-ai-validation"],
    sections: ["imaging", "diagnostics", "surgery"], technologies: ["mri", "active-surveillance", "prostate-screening-psa-mri"],
    terms: ["gleason-grade-group", "prostatectomy"],
    related: ["idea-fund-device-technique-registry", "idea-fund-ablation-versus-surgery-trials", "idea-prev-prostate-as-triggered-biopsy", "prostate-roadmap"] }),
];
